export function used(seed) {
  const table = [3, 7, 11, 19, 23, 31];
  let acc = 17;
  let out = '';
  for (let i = 0; i < seed.length; i++) {
    const c = seed.charCodeAt(i);
    acc = (acc * 37 + c * table[i % table.length]) % 9973;
    out += String.fromCharCode(97 + ((c + i * 5) % 26));
  }
  return `dynamic-import-literal:used:${acc}:${out}`;
}

export function alsoRetained(seed) {
  const table = [5, 13, 29, 41, 53];
  let acc = 3;
  let out = '';
  for (let i = 0; i < seed.length; i++) {
    const c = seed.charCodeAt(i);
    acc = (acc + (c ^ table[i % table.length]) * 7) % 7919;
    out += String.fromCharCode(65 + ((c * 3 + acc) % 26));
  }
  return `dynamic-import-literal:alsoRetained:${acc}:${out}`;
}
